      const fin = v => { if (done) return; if (v != null && confirm) { if (v.length < 8) { msg.textContent = 'Almeno 8 caratteri.'; return; } if (v !== p2.value) { msg.textContent = 'Le due frasi non coincidono.'; return; } } done = true; m.close(); res(v); };
