  const idFromSlug = s => BY_SLUG[s] || (P[s] || (typeof TOOLS !== 'undefined' && TOOLS[s]) ? s : '');
  const meta = id => P[id] ? { title: P[id].title + ' · ' + NAME, desc: P[id].desc } : { title: HOME.title, desc: HOME.desc };
  return { NAME, HOME, P, slug, idFromSlug, meta };
