  const rank = query => [...Object.keys(TOOLS)].map(id => ({ id, s: score(id, query) })).filter(x => x.s > 0).sort((a, b) => b.s - a.s || TOOLS[a.id].title.localeCompare(TOOLS[b.id].title, 'it')).map(x => x.id);
