          const c = lab[o + x]; if (c < 0) continue;
          const q = ccs[c], sw = Math.min(hrun[o + x], vrun[o + x]); q.sw += sw; q.sw2 += sw * sw;
          // bordo: orientamento del gradiente (Sobel sul grigio), pesato con la sua forza
