      for (const q of ccs) { q.w = q.x1 - q.x0; q.h = q.y1 - q.y0; q.swm = q.sw / q.area; q.swcv = Math.sqrt(Math.max(0, q.sw2 / q.area - q.swm * q.swm)) / Math.max(0.5, q.swm); q.dark /= q.area; q.fill = q.area / (q.w * q.h); }
