    for (let y = 0; y < hh; y++) for (let x = 0; x < w; x++) { const v = img.g[(y0 + y) * img.w + x0 + x], i = (y * w + x) * 4; id.data[i] = id.data[i + 1] = id.data[i + 2] = v; id.data[i + 3] = 255; }
    cx.putImageData(id, 0, 0);
