  const AMT = /^(?:(?:€|eur(?:o)?)\s*)?([-−–]?\s*\d{1,3}(?:[.\s']\d{3})*,\d{2}|[-−–]?\d+,\d{2})(?:\s*(?:€|eur(?:o)?))?$/i;
