    if (m) { const t = m[1].replace(/[−]/, '-').replace(/\s/g, ''); const k = Math.max(t.lastIndexOf('.'), t.lastIndexOf(',')); return +(t.slice(0, k).replace(/[.,]/g, '') + '.' + t.slice(k + 1)); }
