          const cand = N.cells.filter(d => headerRow ? (d.x1 > span[0] && d.x1 <= span[1] + c.size * 0.3 && (d.x0 + d.x1) / 2 >= span[0]) : Math.min(d.x1, span[1]) - Math.max(d.x0, span[0]) > 0);
