      const X0 = clamp(Math.floor(b.x * s), 0, W - 1), Y0 = clamp(Math.floor(b.y * s), 0, H - 1), X1 = clamp(Math.ceil((b.x + b.w) * s), X0 + 1, W), Y1 = clamp(Math.ceil((b.y + b.h) * s), Y0 + 1, H);
