      if (o) { const x1 = Math.max(o.x + o.w, b.x + b.w), y0 = Math.min(o.y, b.y), y1 = Math.max(o.y + o.h, b.y + b.h); o.w = x1 - o.x; o.y = y0; o.h = y1 - y0; o.t = (o.t ? o.t + ' ' : '') + (b.t || ''); }
